export function toSpeechSubmitCborValue(v: SpeechSubmit): CborValue {
  const csilMap = new Map<CborValue, CborValue>();
  csilMap.set("kind", v.kind);
  if (v.text !== undefined) csilMap.set("text", v.text);
  csilMap.set("owner", toScopeRefCborValue(v.owner));
  csilMap.set("sources", v.sources.map((csilE): CborValue => toRecordRefCborValue(csilE)));
  csilMap.set("deadline", { tag: 0, value: csilTsToText(v.deadline) });
  csilMap.set("generation", v.generation);
  if (v.profileId !== undefined) csilMap.set("profile_id", v.profileId);
  csilMap.set("request_id", v.requestId);
  if (v.inputDigest !== undefined) csilMap.set("input_digest", v.inputDigest);
  if (v.inputSamples !== undefined) csilMap.set("input_samples", v.inputSamples);
  csilMap.set("retention_seconds", v.retentionSeconds);
  return csilMap;
}

export function fromSpeechSubmitCborValue(value: CborValue): SpeechSubmit {
  return {
    requestId: asString(requireKey(value, "request_id")),
    owner: fromScopeRefCborValue(requireKey(value, "owner")),
    kind: (asEnumMember(asString(requireKey(value, "kind")), ["tts", "stt"]) as "tts" | "stt"),
    generation: asNumber(requireKey(value, "generation")),
    deadline: asTimestamp(requireKey(value, "deadline")),
    retentionSeconds: asNumber(requireKey(value, "retention_seconds")),
    sources: asArray(requireKey(value, "sources")).map((csilE) => fromRecordRefCborValue(csilE)),
    text: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : asString(csilV))(mapGet(value, "text")),
    profileId: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : asString(csilV))(mapGet(value, "profile_id")),
    inputSamples: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : asNumber(csilV))(mapGet(value, "input_samples")),
    inputDigest: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : asBytes(csilV))(mapGet(value, "input_digest")),
  };
}

export function toSpeechSubmitCbor(v: SpeechSubmit): Uint8Array {
  return encodeValue(toSpeechSubmitCborValue(v));
}

export function fromSpeechSubmitCbor(bytes: Uint8Array): SpeechSubmit {
  return fromSpeechSubmitCborValue(decode(bytes));
}

